<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/AccessPolicy.php';

final class VolunteerApprovalExperience
{
    private const ROUTES=['/volunteer/approvals','/admin/volunteer-approvals','/admin/volunteer-approvals/review'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['volunteer_approval_csrf']??=bin2hex(random_bytes(24));
        $staffRoute=str_starts_with($route,'/admin/');if($staffRoute&&!AccessPolicy::isStaff($user))self::forbidden($basePath,$user);
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$route,$basePath,$user);
        if($route==='/volunteer/approvals')self::volunteerPage($db,$basePath,$user);
        $requestId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;self::staffPage($db,$route,$basePath,$user,(int)$requestId);
    }

    private static function handlePost(PDO $db,string $route,string $basePath,array $user):never
    {
        if(!hash_equals((string)($_SESSION['volunteer_approval_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired. Please try again.');self::redirect($basePath.($route==='/volunteer/approvals'?'/volunteer/approvals':'/admin/volunteer-approvals'));}
        $action=(string)($_POST['action']??'');
        try{
            if($route==='/volunteer/approvals'){
                if($action==='request'){self::requestApproval($db,$user,(int)(filter_input(INPUT_POST,'shift_id',FILTER_VALIDATE_INT)?:0),trim((string)($_POST['request_note']??'')));self::flash('success','Approval request submitted. The shift is not reserved until staff approves it.');}
                elseif($action==='withdraw'){self::withdrawRequest($db,$user,(int)(filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT)?:0));self::flash('success','Approval request withdrawn.');}
                self::redirect($basePath.'/volunteer/approvals');
            }
            if(!AccessPolicy::isStaff($user))self::forbidden($basePath,$user);
            $requestId=(int)(filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT)?:0);$note=trim((string)($_POST['decision_note']??''));
            if($action==='approve'){self::decide($db,$user,$requestId,true,$note);self::flash('success','Volunteer approved and added to the shift.');}
            elseif($action==='decline'){self::decide($db,$user,$requestId,false,$note);self::flash('success','Approval request declined. The volunteer was notified.');}
            self::redirect($basePath.'/admin/volunteer-approvals');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());self::redirect($basePath.($route==='/volunteer/approvals'?'/volunteer/approvals':'/admin/volunteer-approvals'));}
    }

    private static function requestApproval(PDO $db,array $user,int $shiftId,string $note):void
    {
        if($shiftId<1)throw new RuntimeException('That volunteer shift could not be found.');if(mb_strlen($note)>500)throw new RuntimeException('Keep the request note under 500 characters.');
        $db->beginTransaction();try{
            $profile=$db->prepare('SELECT active FROM volunteer_profiles WHERE user_id=:user FOR UPDATE');$profile->execute(['user'=>(int)$user['id']]);if(!(bool)$profile->fetchColumn())throw new RuntimeException('Your account does not have an active volunteer profile.');
            $s=$db->prepare('SELECT id,title,approval_required,required_slots FROM volunteer_shifts WHERE id=:id FOR UPDATE');$s->execute(['id'=>$shiftId]);$shift=$s->fetch();if(!$shift)throw new RuntimeException('That volunteer shift no longer exists.');if(!(bool)$shift['approval_required'])throw new RuntimeException('That shift does not require approval; use the normal signup action instead.');
            $missing=self::missingRequirements($db,(int)$user['id'],$shiftId);if($missing)throw new RuntimeException('You cannot request this role yet. Complete: '.implode(', ',$missing).'.');
            $confirmed=$db->prepare("SELECT COUNT(*) FROM volunteer_shift_signups WHERE shift_id=:shift AND user_id=:user AND status IN ('signed_up','checked_in','completed')");$confirmed->execute(['shift'=>$shiftId,'user'=>(int)$user['id']]);if((int)$confirmed->fetchColumn()>0)throw new RuntimeException('You are already confirmed for this shift.');
            $existing=$db->prepare('SELECT id,status FROM volunteer_shift_approval_requests WHERE shift_id=:shift AND user_id=:user FOR UPDATE');$existing->execute(['shift'=>$shiftId,'user'=>(int)$user['id']]);$request=$existing->fetch();if($request&&$request['status']==='pending')throw new RuntimeException('You already have a pending request for this shift.');
            if($request){$save=$db->prepare("UPDATE volunteer_shift_approval_requests SET status='pending',request_note=:note,decision_note=NULL,reviewed_by_user_id=NULL,reviewed_at=NULL,requested_at=CURRENT_TIMESTAMP WHERE id=:id");$save->execute(['note'=>$note!==''?$note:null,'id'=>(int)$request['id']]);$id=(int)$request['id'];}
            else{$save=$db->prepare("INSERT INTO volunteer_shift_approval_requests (shift_id,user_id,status,request_note) VALUES (:shift,:user,'pending',:note)");$save->execute(['shift'=>$shiftId,'user'=>(int)$user['id'],'note'=>$note!==''?$note:null]);$id=(int)$db->lastInsertId();}
            self::audit($db,(int)$user['id'],'volunteer.approval_requested','volunteer_shift_approval_request',$id,'Requested approval for volunteer shift.',['shift_id'=>$shiftId,'shift_title'=>$shift['title']]);$db->commit();
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The approval request could not be submitted.');}
    }

    private static function withdrawRequest(PDO $db,array $user,int $requestId):void
    {
        if($requestId<1)throw new RuntimeException('That request could not be found.');$s=$db->prepare("UPDATE volunteer_shift_approval_requests SET status='withdrawn',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND user_id=:user AND status='pending'");$s->execute(['id'=>$requestId,'user'=>(int)$user['id']]);if($s->rowCount()<1)throw new RuntimeException('That request is no longer pending or does not belong to you.');self::audit($db,(int)$user['id'],'volunteer.approval_withdrawn','volunteer_shift_approval_request',$requestId,'Withdrew volunteer shift approval request.',[]);
    }

    private static function decide(PDO $db,array $reviewer,int $requestId,bool $approve,string $note):void
    {
        if($requestId<1)throw new RuntimeException('That approval request could not be found.');if(mb_strlen($note)>500)throw new RuntimeException('Keep the decision note under 500 characters.');
        $db->beginTransaction();try{
            $s=$db->prepare("SELECT r.id,r.shift_id,r.user_id,r.status,vs.title,vs.required_slots,vs.approval_required,CONCAT(u.first_name,' ',u.last_name) volunteer_name FROM volunteer_shift_approval_requests r JOIN volunteer_shifts vs ON vs.id=r.shift_id JOIN users u ON u.id=r.user_id WHERE r.id=:id FOR UPDATE");$s->execute(['id'=>$requestId]);$r=$s->fetch();if(!$r||$r['status']!=='pending')throw new RuntimeException('That request is no longer pending.');
            if($approve){if(!(bool)$r['approval_required'])throw new RuntimeException('This shift no longer requires approval. Review the shift before continuing.');$missing=self::missingRequirements($db,(int)$r['user_id'],(int)$r['shift_id']);if($missing)throw new RuntimeException('Approval blocked because the volunteer is no longer eligible: '.implode(', ',$missing).'.');$count=$db->prepare("SELECT COUNT(*) FROM volunteer_shift_signups WHERE shift_id=:shift AND status IN ('signed_up','checked_in','completed')");$count->execute(['shift'=>(int)$r['shift_id']]);if((int)$count->fetchColumn()>=(int)$r['required_slots'])throw new RuntimeException('This shift is now full. Decline the request or expand capacity first.');$existing=$db->prepare('SELECT id FROM volunteer_shift_signups WHERE shift_id=:shift AND user_id=:user FOR UPDATE');$existing->execute(['shift'=>(int)$r['shift_id'],'user'=>(int)$r['user_id']]);$signup=(int)($existing->fetchColumn()?:0);if($signup)$db->prepare("UPDATE volunteer_shift_signups SET status='signed_up',created_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['id'=>$signup]);else$db->prepare("INSERT INTO volunteer_shift_signups (shift_id,user_id,status) VALUES (:shift,:user,'signed_up')")->execute(['shift'=>(int)$r['shift_id'],'user'=>(int)$r['user_id']]);}
            $status=$approve?'approved':'declined';$db->prepare('UPDATE volunteer_shift_approval_requests SET status=:status,decision_note=:note,reviewed_by_user_id=:reviewer,reviewed_at=CURRENT_TIMESTAMP WHERE id=:id')->execute(['status'=>$status,'note'=>$note!==''?$note:null,'reviewer'=>(int)$reviewer['id'],'id'=>$requestId]);
            $title=$approve?'Volunteer shift approved':'Volunteer shift request declined';$body=$approve?'You are confirmed for '.$r['title'].'. It is now part of your volunteer commitments.':'Your request for '.$r['title'].' was not approved.';if($note!=='')$body.=' Staff note: '.$note;$db->prepare("INSERT INTO app_notifications (recipient_user_id,source_type,source_id,title,body,action_path) VALUES (:recipient,'volunteer_shift_approval',:source,:title,:body,:path) ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body),action_path=VALUES(action_path),read_at=NULL,created_at=CURRENT_TIMESTAMP")->execute(['recipient'=>(int)$r['user_id'],'source'=>$requestId,'title'=>$title,'body'=>$body,'path'=>'/volunteer/shift?id='.(int)$r['shift_id']]);
            self::audit($db,(int)$reviewer['id'],$approve?'volunteer.approval_approved':'volunteer.approval_declined','volunteer_shift_approval_request',$requestId,($approve?'Approved ':'Declined ').$r['volunteer_name'].' for '.$r['title'].'.',['shift_id'=>(int)$r['shift_id'],'volunteer_user_id'=>(int)$r['user_id'],'decision_note'=>$note!==''?$note:null]);$db->commit();
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The approval decision could not be saved.');}
    }

    private static function missingRequirements(PDO $db,int $userId,int $shiftId):array{$s=$db->prepare("SELECT vr.name FROM volunteer_shift_requirements vsr JOIN volunteer_requirements vr ON vr.id=vsr.requirement_id LEFT JOIN volunteer_credentials vc ON vc.requirement_id=vr.id AND vc.user_id=:user WHERE vsr.shift_id=:shift AND (vc.id IS NULL OR vc.status<>'approved' OR (vc.expires_at IS NOT NULL AND vc.expires_at<NOW())) ORDER BY vr.id");$s->execute(['user'=>$userId,'shift'=>$shiftId]);return $s->fetchAll(PDO::FETCH_COLUMN);}
    private static function volunteerRows(PDO $db,int $userId):array{$s=$db->prepare("SELECT vs.id shift_id,vs.title,vs.category,vs.starts_at,vs.ends_at,vs.location,vs.required_slots,COALESCE(cap.active_signups,0) active_signups,r.id request_id,r.status request_status,r.request_note,r.decision_note,r.requested_at,r.reviewed_at FROM volunteer_shifts vs LEFT JOIN (SELECT shift_id,COUNT(*) active_signups FROM volunteer_shift_signups WHERE status IN ('signed_up','checked_in','completed') GROUP BY shift_id) cap ON cap.shift_id=vs.id LEFT JOIN volunteer_shift_approval_requests r ON r.shift_id=vs.id AND r.user_id=:user WHERE vs.approval_required=1 ORDER BY vs.starts_at");$s->execute(['user'=>$userId]);$rows=$s->fetchAll();foreach($rows as &$row){$row['missing']=self::missingRequirements($db,$userId,(int)$row['shift_id']);$row['eligible_to_request']=!$row['missing']&&(int)$row['active_signups']<(int)$row['required_slots'];$row['open_slots']=max((int)$row['required_slots']-(int)$row['active_signups'],0);}unset($row);return $rows;}
    private static function staffQueue(PDO $db):array{return $db->query("SELECT r.id,r.status,r.request_note,r.decision_note,r.requested_at,r.reviewed_at,vs.id shift_id,vs.title,vs.starts_at,vs.location,CONCAT(u.first_name,' ',u.last_name) volunteer_name,u.initials,CONCAT(rv.first_name,' ',rv.last_name) reviewer_name FROM volunteer_shift_approval_requests r JOIN volunteer_shifts vs ON vs.id=r.shift_id JOIN users u ON u.id=r.user_id LEFT JOIN users rv ON rv.id=r.reviewed_by_user_id ORDER BY FIELD(r.status,'pending','approved','declined','withdrawn'),r.requested_at")->fetchAll();}
    private static function requestDetail(PDO $db,int $requestId):?array{if($requestId<1)return null;$s=$db->prepare("SELECT r.*,vs.title,vs.category,vs.starts_at,vs.ends_at,vs.location,vs.required_slots,COALESCE(cap.active_signups,0) active_signups,CONCAT(u.first_name,' ',u.last_name) volunteer_name,u.initials,u.display_role volunteer_role FROM volunteer_shift_approval_requests r JOIN volunteer_shifts vs ON vs.id=r.shift_id JOIN users u ON u.id=r.user_id LEFT JOIN (SELECT shift_id,COUNT(*) active_signups FROM volunteer_shift_signups WHERE status IN ('signed_up','checked_in','completed') GROUP BY shift_id) cap ON cap.shift_id=vs.id WHERE r.id=:id LIMIT 1");$s->execute(['id'=>$requestId]);$row=$s->fetch();if(!$row)return null;$row['missing']=self::missingRequirements($db,(int)$row['user_id'],(int)$row['shift_id']);return $row;}
    private static function audit(PDO $db,int $actorId,string $eventType,string $subjectType,int $subjectId,string $summary,array $metadata):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:metadata)');$s->execute(['actor'=>$actorId,'event'=>$eventType,'type'=>$subjectType,'id'=>$subjectId,'summary'=>$summary,'metadata'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}

    private static function volunteerPage(PDO $db,string $basePath,array $user):never
    {
        $rows=self::volunteerRows($db,(int)$user['id']);$flash=self::takeFlash();$url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$sub=[['label'=>'Readiness','href'=>'/volunteer-readiness','active'=>false],['label'=>'Opportunities','href'=>'/volunteer-shifts','active'=>false],['label'=>'Approval requests','href'=>'/volunteer/approvals','active'=>true],['label'=>'Training','href'=>'/volunteer/training','active'=>false],['label'=>'Service record','href'=>'/volunteer/history','active'=>false],['label'=>'Verifications','href'=>'/volunteer/verifications','active'=>false]];
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer approvals · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/volunteer-approval.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/volunteer/approvals',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Volunteer','Approval requests',$basePath,$sub);?><div class="approval-page"><?php if($flash):?><div class="approval-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><section class="approval-hero"><div><small>GATED VOLUNTEER ROLES</small><h2>Request access when a role needs a human decision.</h2><p>Your required credentials must already be current. A request does not hold a slot.</p></div></section><div class="approval-list"><?php if(!$rows):?><section class="approval-empty"><b>No approval-gated shifts</b><p>There are no volunteer opportunities that currently require coordinator approval.</p></section><?php else:foreach($rows as $row):?><article class="approval-card"><div class="approval-date"><b><?=$e(date('M',strtotime($row['starts_at'])))?></b><span><?=$e(date('j',strtotime($row['starts_at'])))?></span></div><div class="approval-copy"><small><?=$e(strtoupper($row['category']))?></small><h3><?=$e($row['title'])?></h3><p><?=$e(date('g:i A',strtotime($row['starts_at'])))?>–<?=$e(date('g:i A',strtotime($row['ends_at'])))?> · <?=$e($row['location'])?> · <?=(int)$row['open_slots']?> open</p><?php if($row['missing']):?><div class="approval-warning">Complete <?=$e(implode(' + ',$row['missing']))?> before requesting this role.</div><?php elseif($row['request_status']):?><div class="approval-status <?=$e($row['request_status'])?>"><b><?=$e(ucfirst($row['request_status']))?></b><?php if($row['decision_note']):?><span><?=$e($row['decision_note'])?></span><?php endif;?></div><?php else:?><div class="approval-ready">Requirements current · eligible to request</div><?php endif;?></div><div class="approval-action"><?php if($row['request_status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_approval_csrf'])?>"><input type="hidden" name="action" value="withdraw"><input type="hidden" name="request_id" value="<?=(int)$row['request_id']?>"><button type="submit" class="approval-link">Withdraw request</button></form><?php elseif($row['eligible_to_request']&&$row['request_status']!=='approved'):?><form method="post" class="approval-request-form"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_approval_csrf'])?>"><input type="hidden" name="action" value="request"><input type="hidden" name="shift_id" value="<?=(int)$row['shift_id']?>"><label>Optional note<textarea name="request_note" maxlength="500"></textarea></label><button class="button" type="submit">Request approval</button></form><?php endif;?></div></article><?php endforeach;endif;?></div></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function staffPage(PDO $db,string $route,string $basePath,array $user,int $requestId):never
    {
        $queue=self::staffQueue($db);$selected=$route==='/admin/volunteer-approvals/review'?self::requestDetail($db,$requestId):null;$flash=self::takeFlash();$url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$pending=count(array_filter($queue,static fn(array $r):bool=>$r['status']==='pending'));
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Volunteer operations · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/volunteer-approval.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar('/admin/volunteer-approvals',$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Operations','Volunteer approvals',$basePath);?><div class="approval-page"><?php if($flash):?><div class="approval-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><?php if($route==='/admin/volunteer-approvals'):?><section class="approval-admin-head"><div><small>VOLUNTEER OPERATIONS</small><h2>Approval queue</h2><p>Review gated roles without bypassing credential requirements or shift capacity.</p></div><strong><?=$pending?><span>pending</span></strong></section><div class="approval-queue"><?php if(!$queue):?><section class="approval-empty"><b>No approval requests yet</b></section><?php else:foreach($queue as $row):?><a href="<?=$url('/admin/volunteer-approvals/review?id='.(int)$row['id'])?>" class="approval-queue-row"><i><?=$e($row['initials'])?></i><div><small><?=$e(strtoupper($row['status']))?> · <?=$e(date('M j · g:i A',strtotime($row['requested_at'])))?></small><h3><?=$e($row['volunteer_name'])?></h3><p><?=$e($row['title'])?></p></div><span>Review →</span></a><?php endforeach;endif;?></div><?php elseif(!$selected):?><section class="approval-empty"><b>Request not found</b><a class="button" href="<?=$url('/admin/volunteer-approvals')?>">Back to queue</a></section><?php else:?><section class="approval-review-head"><div><small><?=$e(strtoupper($selected['status']))?></small><h2><?=$e($selected['volunteer_name'])?></h2><p><?=$e($selected['volunteer_role'])?> · requesting <?=$e($selected['title'])?></p></div><a href="<?=$url('/admin/volunteer-approvals')?>">← Queue</a></section><div class="approval-review-grid"><section class="approval-panel"><small>REQUEST CONTEXT</small><h3><?=$e($selected['title'])?></h3><p><?=$e(date('l, M j · g:i A',strtotime($selected['starts_at'])))?> · <?=$e($selected['location'])?></p><?php if($selected['request_note']):?><blockquote><?=$e($selected['request_note'])?></blockquote><?php endif;?></section><section class="approval-panel"><small>ELIGIBILITY RECHECK</small><?php if($selected['missing']):?><div class="approval-warning"><b>Approval blocked</b><p>Missing or expired: <?=$e(implode(', ',$selected['missing']))?></p></div><?php else:?><div class="approval-ready"><b>Credential requirements current</b></div><?php endif;?><?php if($selected['status']==='pending'):?><form method="post" class="approval-decision"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['volunteer_approval_csrf'])?>"><input type="hidden" name="request_id" value="<?=(int)$selected['id']?>"><label>Decision note<textarea name="decision_note" maxlength="500"></textarea></label><div><button class="button" type="submit" name="action" value="approve"<?=$selected['missing']?' disabled':''?>>Approve & confirm shift</button><button class="approval-decline" type="submit" name="action" value="decline">Decline</button></div></form><?php else:?><div class="approval-status <?=$e($selected['status'])?>"><b><?=$e(ucfirst($selected['status']))?></b></div><?php endif;?></section></div><?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function forbidden(string $basePath,array $user):never{http_response_code(403);header('Content-Type:text/plain; charset=utf-8');echo 'Staff only';exit;}
    private static function flash(string $type,string $message):void{$_SESSION['volunteer_approval_flash']=['type'=>$type,'message'=>$message];}
    private static function takeFlash():?array{$f=$_SESSION['volunteer_approval_flash']??null;unset($_SESSION['volunteer_approval_flash']);return is_array($f)?$f:null;}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
